import React, { useState } from 'react';
import Home from './pages/Home';
import Game from './pages/Game';
import About from './pages/About';
import Layout from './components/Layout';
import './styles/globals.css';

function App() {
  const [view, setView] = useState('home'); // 'home', 'game', 'about'
  const [gameMode, setGameMode] = useState(null); // 'deep', 'unfiltered', 'lab'

  const handleStartGame = (modeId) => {
    setGameMode(modeId);
    setView('game');
  };

  const handleBackToHome = () => {
    setView('home');
    setGameMode(null);
  };

  return (
    <Layout>
      {view === 'home' && (
        <div className="animate-in fade-in duration-500">
          <Home onNavigate={handleStartGame} />
        </div>
      )}
      
      {view === 'game' && (
        <div className="animate-in slide-in-from-right duration-500">
          {/* Passamos o modeId e a função de voltar */}
          <Game modeId={gameMode} onBack={handleBackToHome} />
        </div>
      )}

      {view === 'about' && (
        <div className="animate-in slide-in-from-bottom duration-500">
          <About onBack={() => setView('home')} />
        </div>
      )}

      {/* Botão flutuante para o About na Home */}
      {view === 'home' && (
        <button 
          onClick={() => setView('about')}
          className="fixed bottom-8 left-8 text-[10px] text-raw-bone/40 hover:text-raw-cyan uppercase tracking-widest font-bold rotate-90 origin-left z-50 transition-colors"
        >
          About RAW.
        </button>
      )}
    </Layout>
  );
}

export default App;
